def tosymbol_name(name, *modifiers):
    if isinstance(name, str):
        name = Symbol(name)
    if modifiers:
        modifiers = [*modifiers]
        modifiers = [f"{m}" for m in modifiers if m != 1]
        modifiers = "_".join(modifiers)
        name = Symbol(f"{name}_{modifiers}")
