def tosymbol(x: Union[Num, BasicSymbolic], states: None = None, escape: bool = True) -> Symbol:
    """
    Convert `x` to a symbol. `states` are the states of a system, and `escape`
    means if the target has escapes like `val"y(t)"`. If `escape` is false, then
    it will only output `y` instead of `y(t)`.

    # Examples

    ```jldoctest
    julia> @variables t z(t)
    2-element Vector{Num}:
        t
    z(t)

    julia> Symbolics.tosymbol(z)
    Symbol("z(t)")

    julia> Symbolics.tosymbol(z; escape=false)
    :z
    ```
    """
    if states is not None and x in states:
        return Symbol(str(x))
    if isinstance(x, Num):
        x = unwrap(x)
    if isinstance(x, BasicSymbolic):
        if isinstance(x, Differential):
            return Symbol(f"({x.x.name})ˍt")
        if isinstance(x, Term):
            return Symbol(f"({x.name})({', '.join(str(arg) for arg in x.arguments)})")
        if isinstance(x, Call):
            return Symbol(f"({x.name})({', '.join(str(arg) for arg in x.arguments)})")
        if isinstance(x, Operation):
            return Symbol(f"({x.name})({', '.join(str(arg) for argin x.arguments)})")
    if isinstance(x, Constant):
        return Symbol(str(x))
    if isinstance(x, Symbol):
        return Symbol(str(x))
    raise NotImplementedError(f"Cannot convert {type(x)} to a symbol.")

def arguments(x: Union[Num, BasicSymbolic], op: Function) -> List[BasicSymbolic]:
    """
    Get the arguments of the symbolic expression `x` with respect to the operation or function `op`.
    """
    x = unwrap(x)
    if isinstance(x, BasicSymbolic):
        if isinstance(x, Call) and x.name == op:
            args = [arguments(arg, op) for arg in x.arguments] # recurse into each argument and obtain its factors
            args = reduce(vcat, args) # concatenate array of arrays into one array
        else:
            args = [wrap(x)] # base case
    else:
        raise NotImplementedError(f"Cannot get arguments of type {type(x)}")
    return args

def diff2term(O: BasicSymbolic) -> BasicSymbolic:
    """
    Convert a differential variable to a `Term`. Note that it only takes a `Term`
    not a `Num`.

    ```jldoctest
    julia> @variables x t u(x, t) z(t)[1:2]; Dt = Differential(t); Dx = Differential(x);

    julia> Symbolics.diff2term(Symbolics.value(Dx(Dt(u))))
    uˍtx(x, t)

    julia> Symbolics.diff2term(Symbolics.value(Dt(z[1])))
    (zˍt(t))[1]
    ```
    """
    opchain = [] # type: ignore
    inner = O
    while True:
        if isinstance(inner, BSImpl.Term) and inner.f isa Differential:
            if not isinstance(inner.f.order, int):
                raise NotImplementedError("`diff2term` only supports integer order derivatives.")
            opchain.append(inner.f)
            inner = inner.args[0]
        else:
            break
    if not opchain:
        return O
    return rename(inner, diff2term_name(inner, opchain))

def diff2term_name(inner: BasicSymbolic, opchain: List[Differential]) -> str:
    name = str(inner.name)
    for op in opchain:
        name += f"ˍt{op.order}"
    return name

def rename(x: BasicSymbolic, name: str) -> BasicSymbolic:
    """
    Rename a symbolic variable to `name`.
    """
    if isinstance(x, BSImpl.Term):
        return BSImpl.Term(name, x.args, x.metadata)
    if isinstance(x, BSImpl.Call):
        return BSImpl.Call(name, x.args, x.metadata)
    if isinstance(x, BSImpl.Operation):
        return BSImpl.Operation(name, x.args, x.metadata)
    if isinstance(x, BSImpl.Const):
        return BSImpl.Const(name, x.metadata)
    if isinstance(x, BSImpl.Sym):
        return BSImpl.Sym(name, x.metadata)
    raise NotImplementedError(f"Cannot rename type {type(x)}")
